python3 -I -c 'import json,pathlib,re,decimal,collections; base=pathlib.Path("/workspace/results/dapo_gsm8k_seed42");
def lastnum(s):
 a=re.findall(r"(\-?[0-9\.\,]+)",s[-300:]); return next((x for x in reversed(a) if x not in ("",".")),None)
def canon(x):
 try: return decimal.Decimal(x.replace(",",""))
 except: return None
for kind in ("val_generations","rollouts"):
 for f in sorted((x for x in (base/kind).glob("*.jsonl") if not x.name.startswith("._")),key=lambda x:int(x.stem)):
  rows=[json.loads(x) for x in f.open()]; equiv=[]; boxfp=[]; boxfn=[]
  for i,r in enumerate(rows):
   n=lastnum(r["output"]); gt=r["gts"]
   if not r["acc"] and n is not None and canon(n) is not None and canon(n)==canon(gt): equiv.append((i,n,gt,r["output"][-450:]))
   boxes=re.findall(r"\\boxed\s*\{([^{}]*)\}",r["output"])
   if boxes:
    bn=lastnum(boxes[-1])
    if bn is not None and canon(bn)!=canon(gt) and r["acc"]: boxfp.append((i,bn,n,gt,r["output"][-450:]))
    if bn is not None and canon(bn)==canon(gt) and not r["acc"]: boxfn.append((i,bn,n,gt,r["output"][-450:]))
  print(kind,f.stem,"numeric_equivalent_scored_wrong",len(equiv),"boxed_mismatch_scored_correct",len(boxfp),"boxed_correct_scored_wrong",len(boxfn))
  for name,arr in (("EQUIV",equiv),("BOXFP",boxfp),("BOXFN",boxfn)):
   for x in arr[:3]: print(name,x)'

